test('query progress keeps loaded rows browsable and Load more waits for terminal metadata', async ({ page }) => {
	const errors = [];
	page.on('pageerror', error => errors.push(error.message));
	const records = [
		{ type: 'head', version: 1 },
		{ type: 'view', id: 'tuple' },
		{ type: 'vars', values: ['value'] },
		{ type: 'metadata', values: { 'result-offset': 0, 'result-limit': 2,
			'query-result-status': 'evaluating' } },
		{ type: 'rows', values: [
			[{ kind: 'literal', value: 'loaded-zero' }],
			[{ kind: 'literal', value: 'loaded-one' }]
		] },
		{ type: 'progress', values: { 'result-evaluated-count': 1000000,
			'query-elapsed-ms': 3000, 'query-result-status': 'evaluating' } }
	];
	const terminal = { type: 'end', metadata: {
		'result-offset': 0, 'result-limit': 2, 'result-batch-count': 2,
		'result-has-more': true, 'result-next-offset': 2,
		'total-result-count': 1200000, 'query-elapsed-ms': 4200,
		'query-result-status': 'completed'
	} };
	await openQueryPage(page);
	await setBatchSize(page, 2);
	await setEditor(page, valuesQuery(3));
	await page.evaluate(({ initialRecords, finalRecord }) => {
		const encode = values => new TextEncoder().encode(values.map(value => JSON.stringify(value)).join('\n') + '\n');
		const state = { requestCount: 0, requestBody: '', responseController: null, controller: null,
			finished: false };
		const fetcher = (_url, init) => {
			state.requestCount++;
			state.requestBody = init.body.toString();
			const body = new ReadableStream({
				start(controller) {
					state.responseController = controller;
					controller.enqueue(encode(initialRecords));
				}
			});
			return Promise.resolve(new Response(body, { status: 200, headers: {
				'Content-Type': 'application/vnd.rdf4j.workbench-query-v2+ndjson;charset=UTF-8'
			} }));
		};
		state.controller = window.workbench.queryStream.bindMainQueryForm(
			document.getElementById('query-form'), document.getElementById('query-results'), { fetcher });
		state.complete = () => {
			if (!state.finished && state.responseController) {
				state.finished = true;
				state.responseController.enqueue(encode([finalRecord]));
				state.responseController.close();
			}
		};
		window.__queryProgressFixture = state;
		state.controller.submit();
	}, { initialRecords: records, finalRecord: terminal });
	const result = page.locator('#query-results .query-result-layout');
	try {
		await expect.poll(() => page.evaluate(() => window.__queryProgressFixture.requestCount)).toBe(1);
		await expect(page.locator('#query-results')).toHaveAttribute('aria-busy', 'true');
		await expect(result.locator('.query-result-status'))
			.toHaveText('2 loaded rows; 1000000 processed. 3000 ms elapsed…');
		await expect(result.locator('tbody tr[data-query-row-index]')).toHaveCount(2);
		await expect(result.locator('tbody')).toContainText('loaded-zero');
		await expect(result.locator('tbody')).toContainText('loaded-one');
		await expect(result.locator('.query-result-load-more')).toBeHidden();
		const requestBody = await page.evaluate(() => window.__queryProgressFixture.requestBody);
		expect(new URLSearchParams(requestBody).get('query')).toBe(valuesQuery(3));
		expect(new URLSearchParams(requestBody).get('batch-size')).toBe('2');

		const options = result.locator('.query-result-toolbar__disclosures button').filter({ hasText: 'Options' });
		await options.click();
		await result.locator('select[name="result-layout"]').selectOption('records');
		await expect(result.locator('[data-query-record-index="0"]')).toContainText('loaded-zero');
		await expect(result.locator('[data-query-record-index="1"]')).toContainText('loaded-one');
		await expect.poll(() => page.evaluate(() => window.__queryProgressFixture.requestCount)).toBe(1);

		await page.evaluate(() => window.__queryProgressFixture.complete());
		await expect(page.locator('#query-results')).toHaveAttribute('aria-busy', 'false');
		await expect(result.locator('.query-result-status'))
			.toHaveText('2 loaded rows of 1200000 results. Complete query: 4200 ms.');
		await expect(result.locator('.query-result-load-more')).toBeVisible();
		expect(await page.evaluate(() => window.__queryProgressFixture.requestCount)).toBe(1);
		expect(errors).toEqual([]);
	} finally {
		await page.evaluate(() => {
			window.__queryProgressFixture?.complete();
			window.__queryProgressFixture?.controller?.dispose();
		}).catch(() => {});
	}
});

test('main query Load more appends batches, freezes the query, and keeps the virtual window bounded', async ({ page }, testInfo) => {
	test.setTimeout(90000);
	const monitor = monitorExecutions(page);
	await openQueryPage(page);
	const query = valuesQuery(205);
	await setEditor(page, query);
	await page.evaluate(() => {
		const batchSize = document.createElement('input');
		batchSize.type = 'hidden';
		batchSize.name = 'batch-size';
		batchSize.value = '100';
		document.getElementById('query-form').appendChild(batchSize);
	});

	await page.locator('#exec').click();
	await expect.poll(() => monitor.executions.length).toBe(1);
	const result = page.locator('#query-results .query-result-layout');
	await expect(page.locator('#query-results')).toHaveAttribute('aria-busy', 'false');
	await expectCompletedRows(result.locator('.query-result-status'), 100, 205);
	await expect(result.locator('.query-result-load-more')).toBeVisible();
	await setEditor(page, 'SELECT ?different WHERE { FILTER(false) }');

	for (const [expectedRequests, expectedRows] of [[2, 200], [3, 205]]) {
		await result.locator('.query-result-load-more').click();
		await expect.poll(() => monitor.executions.length).toBe(expectedRequests);
		await expect(page.locator('#query-results')).toHaveAttribute('aria-busy', 'false');
		await expectCompletedRows(result.locator('.query-result-status'), expectedRows, 205);
		if (expectedRequests === 2) {
			await expect(result.locator('.query-result-load-more')).toBeVisible();
		}
	}

	const offsets = monitor.executions.map(execution => fieldValue(execution, 'batch-offset'));
	expect(offsets).toEqual(['0', '100', '200']);
	expect(monitor.executions.map(execution => fieldValue(execution, 'batch-size'))).toEqual(['100', '100', '100']);
	expect(monitor.executions.map(execution => fieldValue(execution, 'query'))).toEqual([query, query, query]);
	for (const execution of monitor.executions) {
		expect(fieldValue(execution, 'limit_query')).toBeNull();
		expect(fieldValue(execution, 'know_total')).toBeNull();
		expect(isStreamingAccept(execution.accept)).toBe(true);
	}
	await expect(result.locator('.query-result-load-more')).toBeHidden();
	await expect(result.getByRole('button', { name: /Next|Previous/i })).toHaveCount(0);
	await expect(result.locator('select[name="stream-result-limit"]')).toHaveCount(0);
	await expect(result.locator('.query-result-navigation__label')).toHaveText('205 loaded rows of 205');

	const options = result.locator('.query-result-toolbar__disclosures button').filter({ hasText: 'Options' });
	await options.click();
	await result.locator('select[name="result-layout"]').selectOption('table');
	const tableWrap = result.locator('.query-result-table-wrap');
	await expect.poll(() => tableWrap.locator('tbody tr[data-query-row-index]').count()).toBeLessThanOrEqual(80);
	await expect(result.locator('.query-result-row-position')).toBeVisible();
	await tableWrap.evaluate(element => {
		element.scrollTop = element.scrollHeight;
		element.dispatchEvent(new Event('scroll'));
	});
	await expect.poll(async () => tableWrap.locator('tbody tr[data-query-row-index]').evaluateAll(rows =>
		Math.max(...rows.map(row => Number(row.getAttribute('data-query-row-index')))))).toBeGreaterThanOrEqual(200);
	const rowLocator = result.locator('.query-result-row-position');
	await rowLocator.fill('205');
	await rowLocator.press('Tab');
	await expect(tableWrap.locator('tbody tr[data-query-row-index="204"]')).toHaveCount(1);
	const tableMetrics = await tableWrap.evaluate(element => ({
		dataRows: element.querySelectorAll('tbody tr[data-query-row-index]').length,
		rowsIncludingSpacers: element.querySelectorAll('tbody tr').length,
		resultDomNodes: element.closest('.query-result-layout').querySelectorAll('*').length
	}));
	expect(tableMetrics.dataRows).toBeLessThanOrEqual(80);
	expect(tableMetrics.rowsIncludingSpacers).toBeLessThanOrEqual(82);
	await testInfo.attach('query-load-more-window.json', {
		body: Buffer.from(JSON.stringify({ offsets, tableMetrics }, null, 2)),
		contentType: 'application/json'
	});
	expect(monitor.errors).toEqual([]);
});

