test('compact tuple rows preserve namespaced, directed, typed, nested, unbound, and long RDF terms', async ({ page, request }) => {
	const monitor = monitorExecutions(page);
	await openQueryPage(page);
	const directedStatement = await request.post(`${REPOSITORY_URL}/statements`, {
		headers: { 'Content-Type': 'text/turtle' },
		data: '<urn:load:item> <urn:load:directed-predicate> "مرحبا"@ar--rtl .'
	});
	expect([200, 201, 204]).toContain(directedStatement.status());
	await setBatchSize(page, 1);
	const longValue = `Long lexical ${'row value '.repeat(60)}`;
	const query = `PREFIX ex: <urn:load:>\n`
		+ 'SELECT ?resource ?rtl ?ltr ?language ?typed ?long ?unbound ?nested WHERE {\n'
		+ 'VALUES (?resource ?rtl ?ltr ?language ?typed ?long ?unbound ?nested) {\n'
		+ '  (ex:item "مرحبا"@ar--rtl "Hello"@en--ltr "bonjour"@fr '
		+ '"typed-value"^^ex:datatype "' + longValue + '" UNDEF '
		+ '<<(ex:item ex:inner <<(ex:leaf ex:value "inside"@en--ltr)>>)>>)\n'
		+ '  (ex:item-two "مرحبا"@ar--rtl "Hello"@en--ltr "bonjour"@fr '
		+ '"typed-value"^^ex:datatype "' + longValue + '" UNDEF '
		+ '<<(ex:item ex:inner <<(ex:leaf ex:value "inside"@en--ltr)>>)>>)\n'
		+ '} }';
	await setEditor(page, query);
	await page.locator('#exec').click();
	await expect.poll(() => monitor.executions.length).toBe(1);
	const result = page.locator('#query-results .query-result-layout');
	await expect(page.locator('#query-results')).toHaveAttribute('aria-busy', 'false');
	await expectCompletedRows(result.locator('.query-result-status'), 1, 2);
	await expect(result.locator('.query-result-load-more')).toBeVisible();
	const options = result.locator('.query-result-toolbar__disclosures button').filter({ hasText: 'Options' });
	await options.click();
	await result.locator('select[name="result-layout"]').selectOption('table');
	await result.locator('.query-result-load-more').click();
	await expect.poll(() => monitor.executions.length).toBe(2);
	await expect(page.locator('#query-results')).toHaveAttribute('aria-busy', 'false');
	await expectCompletedRows(result.locator('.query-result-status'), 2, 2);
	const firstRow = result.locator('tbody tr[data-query-row-index="0"]');
	const cells = firstRow.locator('td');
	await expect(cells.nth(0)).toContainText('ex:item');
	await expect(cells.nth(0)).toHaveAttribute('title', 'urn:load:item');
	await expect(cells.nth(1)).toHaveAttribute('lang', 'ar');
	await expect(cells.nth(1)).toHaveAttribute('dir', 'rtl');
	await expect(cells.nth(1)).toContainText('@ar--rtl');
	await expect(cells.nth(2)).toHaveAttribute('lang', 'en');
	await expect(cells.nth(2)).toHaveAttribute('dir', 'ltr');
	await expect(cells.nth(2)).toContainText('@en--ltr');
	await expect(cells.nth(3)).toHaveAttribute('lang', 'fr');
	await expect(cells.nth(4)).toHaveAttribute('title', 'typed-value');
	await expect(cells.nth(5)).toHaveAttribute('title', longValue);
	await expect(cells.nth(6)).toHaveAttribute('aria-label', 'Unbound');
	await expect(cells.nth(7)).toContainText('<< ex:item ex:inner');
	await expect(cells.nth(7)).toContainText('@en--ltr');
	const exploreResources = await Promise.all([cells.nth(0), cells.nth(1)].map(async cell =>
		cell.locator('a').evaluate(anchor => new URL(anchor.href).searchParams.get('resource'))));
	expect(exploreResources).toEqual(['<urn:load:item>', '"مرحبا"@ar--rtl']);
	const exploreHrefs = await Promise.all([cells.nth(0), cells.nth(1)].map(async cell =>
		cell.locator('a').evaluate(anchor => anchor.href)));
	for (const [index, href] of exploreHrefs.entries()) {
		const explorePage = await page.context().newPage();
		const exploreErrors = [];
		explorePage.on('pageerror', error => exploreErrors.push(error.message));
		await explorePage.goto(href, { waitUntil: 'domcontentloaded' });
		await expect(explorePage.locator('#workbench-app')).toHaveAttribute('data-workbench-view', 'explore');
		await expect(explorePage.locator('#resource')).toHaveValue(exploreResources[index]);
		const exploreRow = explorePage.locator('#explore-results table.data tbody tr');
		await expect(exploreRow).toHaveCount(1);
		await expect(exploreRow.locator('td[data-label="subject"]')).toContainText('urn:load:item');
		await expect(exploreRow.locator('td[data-label="predicate"]')).toContainText('urn:load:directed-predicate');
		await expect(exploreRow.locator('td[data-label="object"]')).toHaveText('مرحبا');
		expect(exploreErrors).toEqual([]);
		await explorePage.close();
	}
	const expectedNestedResource = '<< <urn:load:item> <urn:load:inner> '
		+ '<< <urn:load:leaf> <urn:load:value> "inside"@en--ltr >> >>';
	const tableNestedResource = await cells.nth(7).locator('a').evaluate(anchor =>
		new URL(anchor.href).searchParams.get('resource'));
	expect(tableNestedResource).toBe(expectedNestedResource);

	await result.locator('select[name="result-layout"]').selectOption('records');
	const firstRecord = result.locator('[data-query-record-index="0"]');
	const fields = firstRecord.locator('dd');
	await expect(firstRecord.locator('.query-result-record__title')).toHaveText('Record 1');
	await expect(fields.nth(0).locator('a')).toContainText('ex:item');
	await expect(fields.nth(1)).toHaveAttribute('dir', 'rtl');
	await expect(fields.nth(1)).toContainText('@ar--rtl');
	await expect(fields.nth(2)).toHaveAttribute('dir', 'ltr');
	await expect(fields.nth(4)).toHaveAttribute('title', 'typed-value');
	await expect(fields.nth(5)).toHaveAttribute('title', longValue);
	await expect(fields.nth(6)).toHaveAttribute('aria-label', 'Unbound');
	await expect(fields.nth(7)).toContainText('<< ex:item ex:inner');
	const nestedExploreResource = await fields.nth(7).locator('a').evaluate(anchor =>
		new URL(anchor.href).searchParams.get('resource'));
	expect(nestedExploreResource).toBe(expectedNestedResource);
	await expect(result.locator('.query-result-load-more')).toBeHidden();
	expect(monitor.executions.map(execution => fieldValue(execution, 'batch-offset'))).toEqual(['0', '1']);
	if (test.info().project.name === 'chromium') {
		await saveBrowserScreenshot(page, test.info(), 'chromium-compact-rdf-records.png');
	}
	expect(monitor.errors).toEqual([]);
});

async function openQueryPage(page) {
	await page.setViewportSize({ width: 1440, height: 1000 });
	await page.goto(QUERY_URL, { waitUntil: 'domcontentloaded' });
	await page.locator('#query-form').waitFor({ state: 'visible', timeout: 15000 });
	await page.locator('.CodeMirror').first().waitFor({ state: 'visible' });
}

async function saveQueryNamed(page, query, queryName, options = {}) {
	await openQueryPage(page);
	await setEditor(page, query);
	const toggle = page.locator('#save-query-toggle');
	if (await toggle.getAttribute('aria-expanded') !== 'true') {
		await toggle.click();
	}
	await page.locator('#query-name').fill(queryName);
	await page.evaluate(() => window.workbench.query.handleNameChange());
	await expect(page.locator('#save')).toBeEnabled();
	const saveRequest = page.waitForRequest(request => request.method() === 'POST'
		&& /\/query(?:[?#]|$)/.test(request.url())
		&& !isStreamingAccept(request.headers().accept || '')
		&& new URLSearchParams(request.postData() || '').get('action') === 'save');
	const overwriteDialog = options.overwrite ? page.waitForEvent('dialog') : null;
	await page.locator('#save').click();
	await saveRequest;
	if (overwriteDialog) {
		const dialog = await overwriteDialog;
		expect(dialog.message()).toMatch(/overwrite/i);
		await dialog.accept();
	}
	await expect(page.locator('#save-feedback')).toHaveText('Query saved.');
	await openSavedQueryRow(page, queryName);
}

async function openSavedQueryRow(page, queryName) {
	await page.goto(SAVED_QUERIES_URL, { waitUntil: 'domcontentloaded' });
	await page.locator('#saved-queries').waitFor({ state: 'visible' });
	const row = page.locator('.saved-query-row').filter({ hasText: queryName });
	await expect(row).toHaveCount(1);
	const urn = await row.locator('.saved-query-toggle').getAttribute('data-query-urn');
	expect(urn).toBeTruthy();
	if (urn) {
		savedQueryUrns.add(urn);
	}
	return row;
}

async function addSavedBatchSize(form, batchSize) {
	await form.evaluate((element, value) => {
		const batchSizeInput = document.createElement('input');
		batchSizeInput.type = 'hidden';
		batchSizeInput.name = 'batch-size';
		batchSizeInput.value = String(value);
		element.appendChild(batchSizeInput);
	}, batchSize);
}

async function setEditor(page, query) {
	await page.locator('.CodeMirror').first().evaluate((element, value) => {
		element.CodeMirror.setValue(value);
	}, query);
}

function valuesQuery(count) {
	const values = Array.from({ length: count }, (_unused, index) =>
		`(${index} "item-${String(index).padStart(3, '0')}")`).join(' ');
	return `SELECT ?number ?item WHERE { VALUES (?number ?item) { ${values} } } ORDER BY ?number`;
}

function monitorExecutions(page) {
	const monitor = { errors: [], executions: [] };
	page.on('pageerror', error => monitor.errors.push(error.message));
	page.on('request', request => {
		if (request.method() !== 'POST' || !/\/query(?:[?#]|$)/.test(request.url())
				|| !isStreamingAccept(request.headers().accept || '')) {
			return;
		}
		monitor.executions.push({
			url: request.url(),
			accept: request.headers().accept || '',
			requestHeaders: request.allHeaders(),
			response: request.response(),
			contentType: request.headers()['content-type'] || '',
			body: request.postData() || ''
		});
	});
	return monitor;
}

function isStreamingAccept(accept) {
	return accept.includes(STREAM_ACCEPT) || accept.includes(COMPACT_STREAM_ACCEPT);
}

async function setBatchSize(page, batchSize) {
	await page.locator('#query-form').evaluate((form, value) => {
		form.querySelector('[name="batch-size"]')?.remove();
		const control = document.createElement('input');
		control.type = 'hidden';
		control.name = 'batch-size';
		control.value = String(value);
		form.appendChild(control);
	}, batchSize);
}

async function executeQueryAndWait(page, monitor, query, expectedRequestCount) {
	await setEditor(page, query);
	await page.locator('#exec').click();
	await expect.poll(() => monitor.executions.length).toBe(expectedRequestCount);
	await expect(page.locator('#query-results')).toHaveAttribute('aria-busy', 'false');
}

async function executeAndWaitForLoadMore(page, monitor, query, expectedRequestCount, expectedRows, totalRows) {
	await executeQueryAndWait(page, monitor, query, expectedRequestCount);
	await expectCompletedRows(page.locator('#query-results .query-result-status'), expectedRows, totalRows);
	await expect(page.locator('#query-results .query-result-load-more')).toBeVisible();
}

async function expectCompletedRows(status, loadedRows, totalRows) {
	await expect(status).toHaveText(new RegExp(
		`^${loadedRows} loaded rows of ${totalRows} results\\. Complete query: \\d+ ms\\.$`));
}

async function readRowSeekState(scrollport, targetSelector, rowSelector) {
	return scrollport.evaluate((element, selectors) => {
		const rows = Array.from(element.querySelectorAll(selectors.rowSelector));
		const getIndex = row => Number(row.getAttribute(element.matches('.query-result-records')
			? 'data-query-record-index' : 'data-query-row-index'));
		const targetElement = element.querySelector(selectors.targetSelector);
		const target = targetElement && targetElement.getBoundingClientRect();
		const bounds = element.getBoundingClientRect();
		return {
			commitScrollMethod: typeof window.workbench?.queryStream?.QueryResultRenderer?.prototype?.commitScroll,
			rowPositionValue: document.querySelector('.query-result-row-position').value,
			resultStatus: element.closest('.query-result-layout')?.querySelector('.query-result-status')?.textContent,
			scrollTop: element.scrollTop,
			scrollHeight: element.scrollHeight,
			clientHeight: element.clientHeight,
			maxScrollTop: element.scrollHeight - element.clientHeight,
			viewport: { top: bounds.top, bottom: bounds.bottom, height: bounds.height },
			firstRenderedIndex: rows.length ? getIndex(rows[0]) : null,
			lastRenderedIndex: rows.length ? getIndex(rows[rows.length - 1]) : null,
			renderedIndexes: rows.map(getIndex),
			spacers: Array.from(element.querySelectorAll('[data-query-spacer]'), spacer => {
				const rect = spacer.getBoundingClientRect();
				return {
					position: spacer.getAttribute('data-query-spacer'),
					tag: spacer.tagName,
					inlineHeight: spacer.style.height,
					rectHeight: rect.height,
					top: rect.top,
					bottom: rect.bottom
				};
			}),
			target: target ? { top: target.top, bottom: target.bottom, height: target.height,
				text: targetElement.textContent } : null,
			targetVisible: !!target && target.top < bounds.bottom && target.bottom > bounds.top
		};
	}, { targetSelector, rowSelector });
}

async function waitForSettledRow(scrollport, targetSelector, rowSelector, presentation, rowNumber,
		interaction, testInfo) {
	let previousGeometry = '';
	let stableVisibleSamples = 0;
	try {
		await expect.poll(async () => {
			const state = await readRowSeekState(scrollport, targetSelector, rowSelector);
			const geometry = JSON.stringify([state.scrollTop, state.firstRenderedIndex,
				state.lastRenderedIndex, state.target && state.target.top, state.target && state.target.bottom]);
			stableVisibleSamples = state.targetVisible && geometry === previousGeometry
				? stableVisibleSamples + 1 : state.targetVisible ? 1 : 0;
			previousGeometry = geometry;
			return stableVisibleSamples >= 2;
		}, {
			message: `${presentation} ${interaction} seek should render row ${rowNumber}`
		}).toBe(true);
	} catch (error) {
		const failureState = await readRowSeekState(scrollport, targetSelector, rowSelector);
		const failureEvidence = { presentation, rowNumber, interaction, ...failureState };
		console.log(`[keyboard-row-seek-failed] ${JSON.stringify(failureEvidence)}`);
		await testInfo.attach(`keyboard-row-seek-${presentation}-${interaction}-${rowNumber}-failure.json`, {
			body: Buffer.from(JSON.stringify(failureEvidence, null, 2)), contentType: 'application/json'
		});
		throw error;
	}
	return readRowSeekState(scrollport, targetSelector, rowSelector);
}

function fieldValue(execution, name) {
	if (execution.contentType.toLowerCase().includes('multipart/form-data')) {
		const escapedName = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
		const match = execution.body.match(new RegExp(
			`Content-Disposition: form-data; name="${escapedName}"\\r\\n\\r\\n([\\s\\S]*?)\\r\\n--[^\\r\\n]+`, 'i'));
		return match ? match[1] : null;
	}
	return new URLSearchParams(execution.body).get(name);
}

async function captureExecutionNegotiation(execution) {
	const [requestHeaders, response] = await Promise.all([execution.requestHeaders, execution.response]);
	const responseHeaders = response ? response.headers() : {};
	return {
		request: {
			accept: execution.accept,
			acceptEncoding: requestHeaders['accept-encoding'] || ''
		},
		response: {
			status: response ? response.status() : null,
			contentType: responseHeaders['content-type'] || '',
			contentEncoding: responseHeaders['content-encoding'] || '',
			vary: (responseHeaders.vary || '').toLowerCase().split(',').map(value => value.trim()).filter(Boolean)
		}
	};
}

async function saveBrowserScreenshot(page, testInfo, filename) {
	fs.mkdirSync(BROWSER_EVIDENCE_DIR, { recursive: true });
	const screenshotPath = path.join(BROWSER_EVIDENCE_DIR, filename);
	await page.screenshot({ path: screenshotPath, fullPage: true });
	await testInfo.attach(filename, { path: screenshotPath, contentType: 'image/png' });
	console.log(`[workbench-load-more-screenshot] ${screenshotPath}`);
	return screenshotPath;
}

function repositoryConfiguration(repositoryId) {
	return `@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#>.
@prefix config: <tag:rdf4j.org,2023:config/>.
[] a config:Repository ;
   config:rep.id "${repositoryId}" ;
   rdfs:label "Workbench Load more fixture" ;
   config:rep.impl [ config:rep.type "openrdf:SailRepository" ;
      config:sail.impl [ config:sail.type "openrdf:MemoryStore" ; config:mem.persist false ] ].`;
}
